local Singleton = import('Frame.Singleton')

---@class DailyInvestMgr
local DailyInvestMgr = Class("DailyInvestMgr",Singleton)


function DailyInvestMgr:__init()
    self.propertyData = {}
end

function DailyInvestMgr:__delete()
    self.propertyData = nil
    self.controller = nil
end

function DailyInvestMgr:SavePropertyData(data)
    self.propertyData = data
end

function DailyInvestMgr:UpdatePropertyData(attrId,value)
    local isFind = false
    for i, v in pairs(self.propertyData) do
        if v.additionId == attrId then
            v.num = value
            isFind = true
        end
    end
    
    if not isFind then
        table.insert(self.propertyData, {additionId = attrId, num = value })
    end
end

function DailyInvestMgr:GetPropertyData()
    local data = {}
    for i, v in pairs(self.propertyData) do
        data[v.additionId] = v.num
    end
    return data
end

function DailyInvestMgr:OnDestroy()
    self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
    self:Delete()
end

return DailyInvestMgr